import{_ as o,o as d,c as t,ag as c}from"./chunks/framework.DGzMGr_a.js";const m=JSON.parse('{"title":"Changelog (Python)","description":"","frontmatter":{},"headers":[],"relativePath":"changelog/python.md","filePath":"changelog/python.md","lastUpdated":1781588147000}'),a={name:"changelog/python.md"};function i(n,e,s,r,l,h){return d(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="changelog-python" tabindex="-1">Changelog (Python) <a class="header-anchor" href="#changelog-python" aria-label="Permalink to &quot;Changelog (Python)&quot;">​</a></h1><h2 id="_1-2-0-2026-08-07" tabindex="-1">1.2.0 (2026-08-07) <a class="header-anchor" href="#_1-2-0-2026-08-07" aria-label="Permalink to &quot;1.2.0 (2026-08-07)&quot;">​</a></h2><ul><li><code>unescapeHtml</code>: Added. Turns the five entities <code>escapeHtml</code> produces back into their characters. The string is walked once rather than replaced five times in a row, so <code>&amp;amp;lt;</code> comes back as the literal text <code>&amp;lt;</code> instead of being unescaped twice, and only those five entities are recognised, so <code>&amp;nbsp;</code> and <code>&amp;#x27;</code> are left as they are</li><li><code>escapeHtml</code>: Added. Escapes <code>&amp;</code>, <code>&lt;</code>, <code>&gt;</code>, <code>&quot;</code> and <code>&#39;</code> so a value can be dropped into a page as text rather than read as markup. <code>&#39;</code> is written as <code>&amp;#39;</code> where the built-in <code>html.escape</code> writes <code>&amp;#x27;</code>, so this is not a wrapper around it. It lives in the <code>web</code> category, next to <code>getSlug</code>, and leaves <code>escapeRegExp</code> as the pattern-oriented one</li><li><code>objClone</code>: Added. Copies an object, deeply by default and top level only with <code>deep: False</code>. A <code>dict</code>, <code>list</code> and <code>tuple</code> are rebuilt with their contents copied and a <code>set</code> gets a fresh copy, while a <code>datetime</code> (immutable) or a class instance is handed back as it is. A structure that points back at itself is rebuilt with the same shape rather than recursing until the recursion limit is hit</li><li><code>objMerge</code>: Added. Merges any number of objects into one new object, going down through nested dicts, with the later source winning. Two dicts under the same key are merged into a new dict, so neither source is shared with the result or modified. Lists are replaced whole rather than merged index by index as Lodash does, and <code>None</code> is returned when an argument is not a dict</li><li><code>objGet</code>: Added. Reads a nested value out of an object by dot and/or bracket path (<code>a.b.c</code>, <code>list[0]</code>, <code>list[1].d</code>), returning the <code>fallback</code> when the path is not there. A bracket may carry a quoted key, so <code>[&quot;a.b&quot;]</code> reads one key rather than walking two levels, and a stored <code>None</code> counts as a value rather than a missing path</li><li><code>objPick</code>: Added. Returns a new object containing only the listed keys, accepting a single key or a list of keys. Only the top level is inspected, and a key the dict does not have is skipped rather than carried over as <code>None</code></li><li><code>pad</code>: Added. Pads a string until it reaches the given length, with one <code>position</code> option (<code>start</code>, <code>end</code> or <code>both</code>) covering what Lodash splits across <code>pad</code>, <code>padStart</code> and <code>padEnd</code>. <code>both</code> is the default and gives the extra character to the end, a multi-character <code>char</code> is repeated and truncated, and the length is counted in code points so an emoji counts as one in every language</li><li><code>strToConstantCase</code>: Added. Converts a string to <code>CONSTANT_CASE</code>, uppercasing every word and joining them with an underscore. It splits with <code>words</code>, so <code>XMLHttpRequest</code> becomes <code>XML_HTTP_REQUEST</code>. Python and JavaScript apply the full Unicode case mapping where Dart applies the simple one, so <code>straße</code> becomes <code>STRASSE</code> here and <code>STRAßE</code> in Dart, which the documentation states rather than papering over</li><li><code>strToPascalCase</code>: Added. Converts a string to <code>PascalCase</code>, giving every word an uppercase first letter and a lowercase rest. It splits with <code>words</code>, so <code>XMLHttpRequest</code> becomes <code>XmlHttpRequest</code>. <code>capitalizeEachWords</code> stays the one that keeps the original separators</li><li><code>strToKebabCase</code>: Added. Converts a string to <code>kebab-case</code>, lowercasing every word and joining them with a hyphen. It splits with <code>words</code>, so <code>XMLHttpRequest</code> becomes <code>xml-http-request</code>. <code>getSlug</code> stays the URL-oriented one</li><li><code>strToSnakeCase</code>: Added. Converts a string to <code>snake_case</code>, lowercasing every word and joining them with an underscore. It splits with <code>words</code>, so <code>XMLHttpRequest</code> becomes <code>xml_http_request</code> and <code>abc12def</code> becomes <code>abc_12_def</code></li><li><code>strToCamelCase</code>: Added. Converts a string to <code>camelCase</code>, lowercasing the first word and giving every word after it an uppercase first letter. It splits with <code>words</code>, so an acronym stays whole (<code>XMLHttpRequest</code> becomes <code>xmlHttpRequest</code>) and a run of digits is its own word (<code>abc12def</code> becomes <code>abc12Def</code>)</li><li><code>min</code>: Added. Returns the smallest of the given numbers, accepting either n arguments or a single list exactly like <code>sum</code>. Values that are not numbers are skipped, <code>bool</code> among them, and so is <code>nan</code>, which would otherwise win by losing every comparison. An empty input returns <code>None</code></li><li><code>max</code>: Added. Returns the largest of the given numbers, accepting either n arguments or a single list exactly like <code>sum</code>. Values that are not numbers are skipped, <code>bool</code> among them, and so is <code>nan</code>, which would otherwise win by losing every comparison. An empty input returns <code>None</code></li><li><code>floor</code>: Added. Rounds a number down, to the given number of decimal places, a negative precision rounding down to tens, hundreds and so on. Rounding goes toward negative infinity, so <code>floor(-4.006)</code> is <code>-5</code>. The value is read through <code>Decimal(str(value))</code> and shifted by its exponent, so <code>floor(1.1, 1)</code> is <code>1.1</code></li><li><code>ceil</code>: Added. Rounds a number up, to the given number of decimal places, a negative precision rounding up to tens, hundreds and so on. Rounding goes toward positive infinity, so <code>ceil(-4.006)</code> is <code>-4</code>. The value is read through <code>Decimal(str(value))</code> and shifted by its exponent, so <code>ceil(1.1, 1)</code> is <code>1.1</code> and not <code>1.2</code></li><li><code>round</code>: Added. Rounds a number to the given number of decimal places, a negative precision rounding to tens, hundreds and so on. Ties go away from zero rather than to the nearest even number, so unlike the built-in <code>round</code> it answers <code>1</code> for <code>0.5</code> and <code>3</code> for <code>2.5</code>, matching the JavaScript and Dart implementations. The value is read through <code>Decimal(str(value))</code> and shifted by its exponent rather than multiplied by a power of ten, so <code>round(1.005, 2)</code> is <code>1.01</code> and not <code>1</code></li><li><code>clamp</code>: Added. Restricts a number to an inclusive range, returning <code>min</code> below it and <code>max</code> above it. The upper bound is applied first, so <code>min</code> wins when the two are passed the wrong way round, matching Lodash rather than Dart&#39;s <code>num.clamp</code>, which throws</li><li><code>retry</code>: Added. Runs the given function again on failure until it succeeds or the attempts run out, raising the last error if they all fail. <code>times</code> counts total attempts (default <code>3</code>), <code>delay</code> waits between them and <code>backoff</code> multiplies that wait after each failure. It is synchronous and waits with <code>time.sleep</code>, as <code>sleep</code> already does. <code>BaseException</code> is not caught, so <code>KeyboardInterrupt</code> still stops the loop</li><li><code>throttle</code>: Added. Limits how often a function may run to at most once per <code>wait</code> window, the counterpart of <code>debounce</code>. <code>leading</code> and <code>trailing</code> (both <code>True</code> by default) choose which edge of the window runs. The trailing call is scheduled on a background thread, as <code>debounce</code> already does</li><li><code>objInvert</code>: Added. Returns a new object with the keys and values swapped. Values are converted to text because keys are always strings — <code>None</code> becomes <code>null</code> and <code>True</code> becomes <code>true</code>, and a whole <code>float</code> loses its fractional part, so the result matches the JavaScript implementation — and the later entry wins when two share a value</li><li><code>objMapKeys</code>: Added. Returns a new object whose keys are the values returned by the callback, with the values carried over untouched. The callback receives <code>(value, key)</code>, and the later key wins when two map onto the same name</li><li><code>objPickBy</code>: Added. Returns a new object containing only the entries for which the callback returns <code>true</code>. The callback receives <code>(value, key)</code>, and only the top level is inspected</li><li><code>uncapitalizeFirst</code>: Added. Converts the first letter of the entire string to lowercase, the inverse of <code>capitalizeFirst</code>. Only the first character is touched, so <code>TEST</code> becomes <code>tEST</code></li><li><code>escapeRegExp</code>: Added. Escapes every regular expression metacharacter (<code>^ $ . * + ? ( ) [ ] { } |</code> and <code>\\</code>) so a value can be matched literally. Unlike <code>re.escape</code> it leaves <code>-</code>, <code>#</code> and whitespace alone, because those are special only inside a character class or in verbose mode, and escaping them would not match the JavaScript implementation</li><li><code>deburr</code>: Added. Replaces accented Latin letters with their unaccented equivalents (<code>déjà vu</code> becomes <code>deja vu</code>), spelling out <code>Æ</code>, <code>ß</code>, <code>Þ</code>, <code>Œ</code> and <code>Ĳ</code>, and dropping combining marks. Covers the Latin-1 Supplement and Latin Extended-A blocks</li><li><code>words</code>: Added. Splits a string into the words it is made of. Anything that is neither a letter nor a digit separates words, and camelCase boundaries, runs of capitals (<code>XMLHttpRequest</code> is <code>XML</code>, <code>Http</code>, <code>Request</code>) and runs of digits are split as well</li><li><code>arrIntersection</code>: Added. Returns the values that are present in every one of the given arrays. The result is unique and keeps the order of the first array</li><li><code>arrDifference</code>: Added. Returns the values of the first array that are not contained in any of the other arrays. Values are compared by value rather than by identity, so nested lists and dicts are matched as well</li><li><code>arrCompact</code>: Added. Returns a new array with every falsy value removed (<code>None</code>, <code>False</code>, <code>0</code>, <code>&#39;&#39;</code>, <code>nan</code>). An empty list and an empty dict are kept, matching the JavaScript implementation</li></ul><h2 id="_1-1-0-2026-08-04" tabindex="-1">1.1.0 (2026-08-04) <a class="header-anchor" href="#_1-1-0-2026-08-04" aria-label="Permalink to &quot;1.1.0 (2026-08-04)&quot;">​</a></h2><ul><li><strong>BREAKING CHANGES</strong>: <code>isValidFileName</code> now rejects an empty name and any name carrying a control character (<code>U+0000</code>-<code>U+001F</code> or <code>U+007F</code>). <code>NUL</code> is the one that matters: it terminates the path in the system call underneath every filesystem, so a name carrying one was reported as valid and then silently truncated on the way to disk</li><li><strong>BREAKING CHANGES</strong>: <code>isValidFileName</code> now rejects a name ending in a dot or a space on the Windows path. Windows strips it instead of reporting an error, so <code>report.</code> quietly becomes <code>report</code> and overwrites it. Unix keeps them, so they stay valid with <code>unixType</code></li><li><strong>BREAKING CHANGES</strong>: <code>isValidFileName</code> now measures its 255 limit in UTF-8 bytes rather than characters, which is what ext4, APFS and NTFS enforce. <code>&#39;가&#39; * 100</code> is 100 characters but 300 bytes and cannot be created. Counting characters also disagreed with the JavaScript and Dart implementations, which count UTF-16 units where Python counted code points (<code>&#39;😀&#39; * 130</code> was valid here and invalid there)</li><li><strong>BREAKING CHANGES</strong>: <code>headFile</code> and <code>tailFile</code> now replace malformed UTF-8 with <code>U+FFFD</code> instead of raising <code>UnicodeDecodeError</code>, matching the JavaScript and Dart implementations. One bad byte in a log file no longer stops it from being read</li><li><strong>BREAKING CHANGES</strong>: <code>headFile</code> and <code>tailFile</code> now break a line on a lone <code>\\r</code> as well as on <code>\\n</code> and <code>\\r\\n</code>, matching Node&#39;s readline and Dart&#39;s <code>LineSplitter</code>. A file written on a pre-OS X Mac used to come back as a single line</li><li><strong>BREAKING CHANGES</strong>: <code>createDirectory</code> now reports the error when a <em>file</em> already sits at the path. It asked only whether <em>something</em> was there and then answered that there was nothing to do, so no directory existed and nothing said so</li><li><strong>BREAKING CHANGES</strong>: <code>createFile</code> now creates any parent directory the path needs instead of raising <code>FileNotFoundError</code>, matching the Dart implementation</li><li><strong>BREAKING CHANGES</strong>: <code>createFile</code>, <code>deleteFile</code> and <code>moveFile</code> now treat a path of nothing but whitespace as no path at all, matching the Dart implementation. <code>createFile(&#39; &#39;)</code> used to create a file literally named <code></code></li><li><strong>BREAKING CHANGES</strong>: <code>getFileInfo</code> and <code>getFileSize</code> now raise the original <code>OSError</code> instead of a plain <code>Exception</code> carrying only its text. <code>errno</code>, <code>strerror</code> and <code>filename</code> were dropped with it, so a caller could not tell a missing file from a permission error. The unreachable <code>return</code> both functions ended with has been removed</li><li><strong>BREAKING CHANGES</strong>: <code>getFileInfo</code> now builds <code>dirname</code> with <code>os.path</code>, which follows the host platform, instead of always splitting on <code>/</code>. A Windows path used to come back whole</li><li><strong>BREAKING CHANGES</strong>: <code>toValidFilePath</code> now resolves a leading <code>..</code> against the root, so <code>&#39;../../etc/passwd&#39;</code> returns <code>/etc/passwd</code> instead of <code>/../../etc/passwd</code></li><li><code>isFileHidden</code>: Read the attribute letters out of the column <code>attrib</code> prints them in. Removing the caller&#39;s path from the output failed whenever a relative path was given, because <code>attrib</code> answers with an absolute one, and any <code>H</code> in a directory name then read as hidden</li><li><code>headFile</code>: Read the file in chunks instead of pulling all of it into memory with a single <code>read()</code>. Asking for the first line of a 108 MB log held 476 MB at once and now holds a chunk</li><li><code>tailFile</code>: Read backwards from the end of the file a chunk at a time instead of walking it from the start, and stop popping the front of a <code>length</code>-sized list once per line. The old shape cost <code>lines × length</code>: on a 108 MB log the last 20,000 lines took 6.8 seconds and now take 0.06, and the last single line went from 0.28 seconds to 0.001</li><li><code>getCopyFileName</code>: Accept a <code>set</code> as well as a list, and read it as it is. Naming n files into one directory calls this n times, and rebuilding the set on every call made that loop quadratic — 16,000 names took 11 seconds through a list and 0.03 seconds through a reused <code>set</code></li><li><code>moveFile</code>: Fall back to a copy and a remove when the operating system reports <code>EXDEV</code>. <code>os.rename</code> cannot cross a filesystem boundary, so moving out of the temporary directory, into a mounted volume or onto another drive failed outright</li><li><code>isFileExists</code>: Drop the <code>os.access</code> call whose result was thrown away, halving the system calls this makes</li><li><code>getFileInfo</code>: Read the directory flag out of the <code>stat</code> result already in hand instead of asking the filesystem a second time through <code>os.path.isdir</code></li><li><code>createDirectory</code>: Drop the <code>isFileExists</code> call that ran before every <code>makedirs</code>. <code>makedirs</code> with <code>exist_ok</code> is already a no-op for an existing directory</li><li><code>hasBadWords</code>: Catch a banned word broken up by digits (<code>ad1min</code>, <code>사1과</code>, <code>사123과</code>), a common way of hiding a word in Korean. A digit that opens or closes a word is still read as a letter, so a number in front of a word (<code>2시 발표</code>) is not read away</li></ul><h2 id="_1-0-0-2026-07-28" tabindex="-1">1.0.0 (2026-07-28) <a class="header-anchor" href="#_1-0-0-2026-07-28" aria-label="Permalink to &quot;1.0.0 (2026-07-28)&quot;">​</a></h2><ul><li><strong>BREAKING CHANGES</strong>: <code>encrypt</code> and <code>decrypt</code> now honour the <code>algorithm</code> argument. Every algorithm silently produced AES-CBC before, so a value such as <code>aes-256-gcm</code> was accepted but ignored and the output did not match the JavaScript implementation. AEAD modes (GCM) now carry the authentication tag as <code>iv:authTag:encrypted</code>; the <code>iv:encrypted</code> format for CBC is unchanged. The key length is validated against the algorithm, as it is in JavaScript</li><li><strong>BREAKING CHANGES</strong>: <code>decrypt</code> now validates PKCS7 padding, so decrypting with the wrong key raises instead of quietly returning an empty string</li><li><strong>BREAKING CHANGES</strong>: <code>generateLicense</code> now normalizes the <code>type</code> argument correctly, so <code>&#39;Apache 2.0&#39;</code>, <code>&#39;apache-2.0&#39;</code> and <code>&#39;BSD 3&#39;</code> return the license they name instead of silently falling back to MIT (a missing character class in the normalizing regular expression made it a no-op)</li><li><strong>BREAKING CHANGES</strong>: <code>numberHash</code> and <code>strToAscii</code> now iterate UTF-16 code units, like the JavaScript and Dart implementations. <code>ord()</code> returns a code point, so characters outside the BMP produced different values (<code>&#39;😀&#39;</code> hashed to <code>128512</code> instead of <code>1772899</code>)</li><li><strong>BREAKING CHANGES</strong>: <code>numUnique</code> now returns a millisecond timestamp combined with a per-millisecond sequence (16 digits) instead of a timestamp combined with a random number (18 digits). Repeated calls within a process are now always unique and strictly increasing</li><li><strong>BREAKING CHANGES</strong>: <code>isEqual</code> and <code>isEqualStrict</code> now compare dicts instead of mistaking them for an argument list. Iterating a dict yielded its keys, so every dict comparison returned <code>False</code>. Passing the operands as a list or tuple still works</li><li><strong>BREAKING CHANGES</strong>: <code>objDeleteKeyByValue</code>, <code>objUpdate</code>, <code>arrShuffle</code>, <code>arrMove</code>, <code>sortNumeric</code> and <code>sortByObjectKey</code> no longer modify the argument they are given; they all return a new dict or list</li><li><strong>BREAKING CHANGES</strong>: <code>arrShuffle</code> now returns a list when given a single element, instead of returning that element itself</li><li><strong>BREAKING CHANGES</strong>: <code>sortNumeric</code> and <code>sortByObjectKey</code> now apply <code>descending</code> through the sort key instead of reversing the sorted result, so equal elements keep their relative order</li><li><strong>BREAKING CHANGES</strong>: <code>safeParseInt</code> now treats <code>0</code> as a valid input instead of a missing one, so <code>safeParseInt(0, 99)</code> returns <code>0</code></li><li><strong>BREAKING CHANGES</strong>: <code>trim</code> now returns <code>None</code> for any non-string input instead of raising an <code>AttributeError</code> on truthy values such as <code>trim(123)</code></li><li><code>strBlindRandom</code>: Keep the result the same length as the input. The character that was checked and the character that was masked were one position apart, and the index could land past the end of the string and append instead of mask</li><li><code>generateLicense</code>: Accept an options <code>dict</code> as the first positional argument, like the rest of the package</li><li><code>is2dArray</code>: Return on the first nested list instead of building a filtered copy of the whole list (640ms to 0ms on a 100,000 element list)</li><li><code>isBotAgent</code>: Remove 84 of the 172 alternatives that were substrings of another one (<code>bot</code> already matches <code>naverbot</code>, <code>bingbot</code>, ...) and could never change the outcome — verified identical on 200,000 inputs. Roughly halves the matching cost</li><li><code>numUnique</code>: Stop building an 89,999 element list on every call to pick a single number</li><li><code>capitalizeEachWords</code>: Look the stop words up in a <code>frozenset</code> instead of scanning a list through <code>contains</code></li><li><strong>BREAKING CHANGES</strong>: <code>duration</code> now hides milliseconds by default (enable with <code>withMilliSeconds</code>) and uses grammatically correct plurals (e.g. <code>0 Hours</code>, <code>1 Hour</code>)</li><li><strong>BREAKING CHANGES</strong>: <code>getFilePathLevel</code> no longer counts a trailing separator as an extra level (<code>/home/user/</code> now returns the same level as <code>/home/user</code>)</li><li><strong>BREAKING CHANGES</strong>: <code>getCopyFileName</code> now preserves the original file extension casing (e.g. <code>Report.PDF</code> copies to <code>Report (1).PDF</code> instead of <code>Report (1).pdf</code>)</li><li><strong>BREAKING CHANGES</strong>: <code>isValidFileName</code> now validates the whole name including its extension (so <code>hello.:txt</code> is invalid) and rejects Windows device names (<code>CON</code>, <code>NUL</code>, <code>COM1</code>-<code>COM9</code>, <code>LPT1</code>-<code>LPT9</code>, etc.)</li><li><strong>BREAKING CHANGES</strong>: <code>createFileWithDummy</code> now creates an empty file for a size of <code>0</code> instead of throwing, and throws a clearer error for a negative size</li><li><strong>BREAKING CHANGES</strong>: <code>getParentFilePath</code> now returns the root (<code>/</code> or <code>\\</code>) for an empty or single-segment path instead of <code>/.</code></li><li><strong>BREAKING CHANGES</strong>: <code>toValidFilePath</code> now returns the root (<code>/</code> or <code>\\</code>) for a path that collapses to nothing instead of <code>/.</code></li><li><code>duration</code>: Support <code>Month</code> (30 days) and <code>Year</code> (365 days) units, and add <code>withMilliSeconds</code>, <code>maxUnitCount</code>, and <code>unit</code> (single-unit) options</li><li><code>getParsedInfoFromAddress</code>: Add <code>getParsedInfoFromAddress</code> method</li><li><code>getSlug</code>: Add <code>getSlug</code> method</li><li><code>hasBadWords</code>: Add <code>hasBadWords</code> method</li></ul><h2 id="_0-1-0-2026-06-16" tabindex="-1">0.1.0 (2026-06-16) <a class="header-anchor" href="#_0-1-0-2026-06-16" aria-label="Permalink to &quot;0.1.0 (2026-06-16)&quot;">​</a></h2><ul><li>Initial release of the Python package</li><li>Add <code>string</code> utilities: <code>capitalizeEachWords</code>, <code>capitalizeEverySentence</code>, <code>capitalizeFirst</code>, <code>getGroupKeys</code>, <code>getStrBytes</code>, <code>removeNewLine</code>, <code>removeSpecialChar</code>, <code>replaceBetween</code>, <code>split</code>, <code>strBlindRandom</code>, <code>strCount</code>, <code>strRandom</code>, <code>strShuffle</code>, <code>strToAscii</code>, <code>strUnique</code>, <code>trim</code>, <code>truncate</code>, <code>truncateExpect</code>, <code>urlJoin</code></li><li>Add <code>array</code> utilities: <code>arrCount</code>, <code>arrGroupByMaxCount</code>, <code>arrMove</code>, <code>arrPick</code>, <code>arrRepeat</code>, <code>arrShuffle</code>, <code>arrTo1dArray</code>, <code>arrUnique</code>, <code>arrWithDefault</code>, <code>arrWithNumber</code>, <code>average</code>, <code>sortByObjectKey</code>, <code>sortNumeric</code></li><li>Add <code>object</code> utilities: <code>objDeleteKeyByValue</code>, <code>objFindItemRecursiveByKey</code>, <code>objMergeNewKey</code>, <code>objTo1d</code>, <code>objToArray</code>, <code>objToPrettyStr</code>, <code>objToQueryString</code>, <code>objUpdate</code></li><li>Add <code>date</code> utilities: <code>createDateListFromRange</code>, <code>dateToYYYYMMDD</code>, <code>dayDiff</code>, <code>isValidDate</code>, <code>today</code></li><li>Add <code>format</code> utilities: <code>duration</code>, <code>fileSizeFormat</code>, <code>numberFormat</code>, <code>safeJSONParse</code>, <code>safeParseInt</code></li><li>Add <code>math</code> utilities: <code>div</code>, <code>mul</code>, <code>numPick</code>, <code>numUnique</code>, <code>sub</code>, <code>sum</code></li><li>Add <code>verify</code> utilities: <code>between</code>, <code>contains</code>, <code>is2dArray</code>, <code>isEmail</code>, <code>isEmpty</code>, <code>isEqual</code>, <code>isEqualStrict</code>, <code>isObject</code>, <code>isTrueMinimumNumberOfTimes</code>, <code>isUrl</code>, <code>len</code></li><li>Add <code>web</code> utilities: <code>generateLicense</code>, <code>isBotAgent</code>, <code>isMatchPathname</code>, <code>isMobile</code>, <code>removeLocalePrefix</code></li><li>Add <code>misc</code> utilities: <code>debounce</code>, <code>funcTimes</code>, <code>logBox</code>, <code>sleep</code> (async functions are implemented synchronously)</li><li>Add <code>crypto</code> utilities: <code>decodeBase64</code>, <code>decrypt</code>, <code>encodeBase64</code>, <code>encrypt</code>, <code>md5Hash</code>, <code>numberHash</code>, <code>objectId</code>, <code>sha1Hash</code>, <code>sha256Hash</code>, <code>sha512Hash</code> (<code>encrypt</code>/<code>decrypt</code> use the <code>cryptography</code> package)</li><li>Add <code>file</code> utilities: <code>createDirectory</code>, <code>createFile</code>, <code>createFileWithDummy</code>, <code>deleteAllFileFromDirectory</code>, <code>deleteFile</code>, <code>getCopyFileName</code>, <code>getFileExtension</code>, <code>getFileHashFromPath</code>, <code>getFileHashFromStream</code>, <code>getFileInfo</code>, <code>getFileName</code>, <code>getFilePathLevel</code>, <code>getFileSize</code>, <code>getParentFilePath</code>, <code>headFile</code>, <code>isFileExists</code>, <code>isFileHidden</code>, <code>isValidFileName</code>, <code>joinFilePath</code>, <code>moveFile</code>, <code>normalizeFile</code>, <code>tailFile</code>, <code>toPosixFilePath</code>, <code>toValidFilePath</code></li><li>Add <code>os</code> utilities: <code>getCpu</code>, <code>getHostname</code>, <code>getMachineId</code>, <code>getRamSize</code>, <code>getSid</code>, <code>getUptime</code>, <code>runCommand</code></li><li>Add <code>net</code> utility: <code>fetchData</code></li></ul>',9)])])}const g=o(a,[["render",i]]);export{m as __pageData,g as default};
